/* Vendor purchases use saved invoice amounts and historical item prices. */
reports.push(['report-vendor-purchases','Vendor-wise Spare Parts Purchases']);titles['report-vendor-purchases']='Vendor-wise Spare Parts Purchases';
let purchaseVendorFilter='',purchasePartFilter='',purchaseLocationFilter='';
function vendorKey(value){return String(value||'').trim().replace(/\s+/g,' ').toLocaleLowerCase()||'(unspecified vendor)'}
function purchaseVendorOptions(){let vendors=new Map();for(let p of db.purchases)if(p.status!=='Cancelled'){for(let line of (p.partLines||[])){let value=line.vendor||p.supplier,key=vendorKey(value);if(!vendors.has(key))vendors.set(key,String(value||'Unspecified Vendor').trim())}}return [...vendors].map(([value,label])=>({value,label})).sort((a,b)=>a.label.localeCompare(b.label))}
function vendorPurchaseData(){
 let invoices=[],lines=[];if(reportFrom&&reportTo&&reportFrom>reportTo)return {invoices,lines,vendors:[]};
 for(let bill of db.purchases){if(bill.status==='Cancelled'||reportFrom&&bill.date<reportFrom||reportTo&&bill.date>reportTo||purchaseLocationFilter&&(bill.stockLocation||'main')!==purchaseLocationFilter)continue;
 let items=(bill.partLines||[]).filter(line=>!purchasePartFilter||line.part===purchasePartFilter).map(line=>{let part=find('parts',line.part),qty=Number(line.qty||0),price=Number(line.price||0),base=round(qty*price),discount=itemDiscount(line,'part'),net=round(base-discount),gst=bill.invoiceType==='non-gst'?0:Number(line.gst||0),tax=round(net*gst/100),vendor=String(line.vendor||bill.supplier||'Unspecified Vendor').trim();return {vendor,bill:bill.id,invoice:bill.invoice||'',date:bill.date,location:bill.stockLocation==='godown'?'Godown':'Main Stock',part:line.part,name:line.name||part?.name||'Removed part',make:part?.vehicleMake||'',model:part?.vehicleModel||'',unit:part?.unit||'PCS',qty,price,discount,net,gst,tax,total:round(net+tax)}}).filter(line=>!purchaseVendorFilter||vendorKey(line.vendor)===purchaseVendorFilter).filter(line=>!search||matches({...line,supplier:line.vendor}));
 if(!items.length)continue;lines.push(...items);invoices.push({bill,items,total:billTotals(bill).total,paid:paid(bill),due:due(bill)});
 }
 let grouped=new Map();for(let item of invoices){for(let line of item.items){let key=vendorKey(line.vendor);if(!grouped.has(key))grouped.set(key,{vendor:line.vendor,count:0,parts:new Set(),net:0,tax:0,total:0,paid:0,due:0});let v=grouped.get(key);v.count++;v.parts.add(line.part);v.net+=line.net;v.tax+=line.tax;v.total+=item.total;v.paid+=item.paid;v.due+=item.due}}
 let vendors=[...grouped.values()].map(v=>({...v,parts:v.parts.size,net:round(v.net),tax:round(v.tax),total:round(v.total),paid:round(v.paid),due:round(v.due)})).sort((a,b)=>a.vendor.localeCompare(b.vendor));
 return {invoices,lines,vendors};
}
function vendorPurchaseTables(data,raw=false){let summaryHeaders=['Vendor','Purchase Entries','Unique Parts','Filtered Parts Value (excl. GST)','Filtered Item GST','Invoice Total','Paid','Due'],summaryRows=data.vendors.map(v=>[v.vendor,v.count,v.parts,v.net,v.tax,v.total,v.paid,v.due]);let detailHeaders=['Vendor','Purchase Date','Purchase ID','Supplier Invoice / Bill No.','Received Into','SKU','Spare Part','Vehicle Make','Vehicle Model','Unit','Quantity','Purchase Cost / Unit','Item Discount','Parts Value (excl. GST)','GST (%)','Item GST','Item Total'],detailRows=data.lines.map(l=>[l.vendor,l.date,l.bill,l.invoice,l.location,l.part,l.name,l.make,l.model,l.unit,l.qty,l.price,l.discount,l.net,l.gst,l.tax,l.total]);let invoiceHeaders=['Vendor','Purchase Date','Purchase ID','Supplier Invoice / Bill No.','Received Into','Invoice Total','Paid','Due'],invoiceRows=data.invoices.map(i=>[i.bill.supplier||'Unspecified Vendor',i.bill.date,i.bill.id,i.bill.invoice||'',i.bill.stockLocation==='godown'?'Godown':'Main Stock',i.total,i.paid,i.due]);
 if(raw)return [{title:'Vendor Summary',headers:summaryHeaders,rows:summaryRows},{title:'Spare Part Purchase Details',headers:detailHeaders,rows:detailRows},{title:'Matching Purchase Invoices',headers:invoiceHeaders,rows:invoiceRows}];
 return vendorPurchaseTables(data,true).map(section=>'<h3>'+section.title+'</h3>'+table(section.headers,section.rows.map(row=>row.map(value=>typeof value==='number'?esc(Number.isInteger(value)?value:round(value)):esc(value||'—'))))).join('');
}
function vendorPurchaseReport(){let data=vendorPurchaseData();return '<div class="intro"><h2>Vendor-wise Spare Parts Purchase Report</h2><p>Saved supplier purchases with item costs, invoice references and main/godown destinations.</p></div>'+summary([['VENDORS',data.vendors.length],['MATCHING PURCHASES',data.invoices.length],['FILTERED PARTS VALUE (EXCL. GST)',money(data.lines.reduce((n,l)=>n+l.net,0))],['MATCHING INVOICE TOTAL',money(data.invoices.reduce((n,i)=>n+i.total,0))]])+'<div class="toolbar vendorPurchaseFilters"><input id="search" class="search" placeholder="Search vendor, invoice, part or SKU..." aria-label="Search vendor purchase report" value="'+esc(search)+'"><select id="purchaseVendorFilter" aria-label="Filter purchase vendor"><option value="">All Vendors</option>'+opts(purchaseVendorOptions(),purchaseVendorFilter)+'</select><select id="purchasePartFilter" aria-label="Filter purchased spare part"><option value="">All Spare Parts</option>'+opts(db.parts.map(p=>({value:p.id,label:p.name+' — '+p.id})),purchasePartFilter)+'</select><select id="purchaseLocationFilter" aria-label="Filter purchase stock location"><option value="">Main & Godown</option>'+opts([{value:'main',label:'Main Stock'},{value:'godown',label:'Godown'}],purchaseLocationFilter)+'</select><label>From <input type="date" id="reportFrom" value="'+esc(reportFrom)+'"></label><label>To <input type="date" id="reportTo" value="'+esc(reportTo)+'"></label><button class="btn secondary" id="resetVendorPurchase">Reset</button><button class="btn success" id="exportVendorPurchase">Export Excel</button><button class="btn secondary" id="printVendorPurchase">'+icon('print')+' Print / Preview</button></div>'+(reportFrom&&reportTo&&reportFrom>reportTo?'<div class="notice">From date must be on or before To date.</div>':'')+'<div class="notice">Amounts are in INR. Item values use saved purchase prices, not current master prices. Invoice Total, Paid and Due cover each matching invoice once, including its other items and invoice-level discounts. With a part/search filter these invoice figures are not allocated to the filtered parts. Quantities remain per item/unit.</div>'+(!data.lines.length?'<p class="notice">No purchases match these filters. Save supplier purchases first; opening-stock entries and transfers are not supplier purchases.</p>':'')+vendorPurchaseTables(data)}
const reportBeforeVendorPurchases=reportPage;
reportPage=function(){return page==='report-vendor-purchases'?vendorPurchaseReport():reportBeforeVendorPurchases()};
function exportVendorPurchases(){let sections=vendorPurchaseTables(vendorPurchaseData(),true),rows=[['Vendor-wise Spare Parts Purchases'],['Vendor',purchaseVendorOptions().find(v=>v.value===purchaseVendorFilter)?.label||'All Vendors','From',reportFrom||'All Time','To',reportTo||'All Time'],['Amounts in INR; invoice totals include the full matching invoice, not only filtered items.'],...sections.flatMap(s=>[[s.title],s.headers,...s.rows,[]])];let csv=rows.map(row=>row.map(v=>{let text=String(typeof displayDate==='function'?displayDate(v??''):v??'');if(typeof v==='string'&&/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');download('\ufeff'+csv,'BIKE-DOCTOR-vendor-purchases-'+today()+'.csv','text/csv;charset=utf-8')}
const renderBeforeVendorPurchases=render;
render=function(){renderBeforeVendorPurchases();if(page==='purchases'){let toolbar=$('#content .toolbar');if(toolbar&&!toolbar.querySelector('[data-vendor-report-link]'))toolbar.insertAdjacentHTML('beforeend','<button type="button" class="btn secondary" data-vendor-report-link data-page="report-vendor-purchases">Vendor Purchase Report</button>')}if(page!=='report-vendor-purchases')return;for(let [id,set]of [['purchaseVendorFilter',v=>purchaseVendorFilter=v],['purchasePartFilter',v=>purchasePartFilter=v],['purchaseLocationFilter',v=>purchaseLocationFilter=v]])if($('#'+id))$('#'+id).onchange=e=>{set(e.target.value);render()};if($('#resetVendorPurchase'))$('#resetVendorPurchase').onclick=()=>{purchaseVendorFilter='';purchasePartFilter='';purchaseLocationFilter='';reportFrom='';reportTo='';search='';render()};if($('#exportVendorPurchase'))$('#exportVendorPurchase').onclick=exportVendorPurchases;if($('#printVendorPurchase'))$('#printVendorPurchase').onclick=()=>{let vendor=purchaseVendorOptions().find(v=>v.value===purchaseVendorFilter)?.label||'All Vendors';openModal('Vendor-wise Spare Parts Purchases','<div class="invoice vendorPurchasePrint"><h2>'+esc(db.settings.name)+' — Vendor Purchase Report</h2><p>'+esc(vendor)+' · '+esc(reportFrom||'All Time')+' to '+esc(reportTo||'All Time')+'</p><p>Amounts in INR. Invoice totals include all items in each matching invoice, not just filtered parts.</p>'+vendorPurchaseTables(vendorPurchaseData())+'</div><div class="formactions">'+btn('Close','cancel','secondary')+'<button class="btn" id="printVendorPurchaseSheet">Print / Save PDF</button></div>');$('#printVendorPurchaseSheet').onclick=printA4Invoice}};
if(location.hash==='#report-vendor-purchases'){page='report-vendor-purchases';reportMenuOpen=true}render();
